import AppKit

/// Brand images embedded in code — no file access, no permissions prompt.
enum BrandAssets {
    private static func image(from b64: String) -> NSImage? {
        guard let data = Data(base64Encoded: b64), let img = NSImage(data: data) else { return nil }
        return img
    }
    static var sherlock: NSImage? { image(from: sherlockB64) }
    static var githubMark: NSImage? { image(from: githubB64) }
    private static let sherlockB64 = """

"""
    private static let githubB64 = """

"""
}
